import { useMemo, useState } from 'react';
import indexStyles from '../SpecIndex/styles.module.css';
import styles from './styles.module.css';

// The release view and the topic view of a specification map, generated by
// Standards2Deployments (tools/explore/specmap.py) into src/data/specmap/<slug>.json.
// Nothing here is computed beyond what the file states. A release in which a
// document had no issue of its own leaves the earlier issue in force; a release
// that was not analysed shows no statement counts (the file has null there).

const label = (r) => `Release ${r}`;

const clamp = (t, n = 240) => {
  if (!t || t.length <= n) return t;
  const cut = t.slice(0, n).replace(/\s+\S*$/, '');
  return `${cut} ...`;
};

// Adapter: the specification map as the entries SpecIndex reads. The note is the first sentence of the
// document's Scope clause, verbatim (shortened with "..." when long).
export function specsFromMap(map) {
  return map.documents.map((d) => ({
    id: d.id,
    title: d.title,
    url: d.url,
    layer: d.layer,
    release: d.firstRelease,
    note: d.scope ? clamp(d.scope.firstSentence) : undefined,
  }));
}

const list = (items) =>
  items.length <= 1 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;

// What the map says at a glance: how many documents, of which kind, and what each release did.
export function SpecGlance({ map }) {
  const docs = map.documents;
  const ts = docs.filter((d) => d.kind === 'TS').map((d) => d.id);
  const tr = docs.filter((d) => d.kind === 'TR').map((d) => d.id);
  const open = map.releases.open || [];
  const rels = [...map.releases.analysed, ...map.releases.tracking];
  const lines = rels
    .map((r) => {
      const created = docs.filter((d) => d.firstRelease === r).map((d) => d.id);
      const issued = docs
        .filter((d) => d.firstRelease !== r && d.releases && d.releases[r] && d.releases[r].newIssue)
        .map((d) => d.id);
      const parts = [];
      if (created.length) parts.push(`creates ${list(created)}`);
      if (issued.length) parts.push(`publishes new issues of ${list(issued)}`);
      return parts.length ? { r, text: parts.join('; ') } : null;
    })
    .filter(Boolean);
  return (
    <ul>
      <li>
        <strong>{docs.length} documents:</strong> {ts.length} specifications ({list(ts)}) and {tr.length} reports ({list(tr)}).
      </li>
      <li>
        <strong>By release:</strong>
        <ul>
          {lines.map(({ r, text }) => (
            <li key={r}>
              Release {r}{open.includes(r) ? ' (in progress)' : ''} {text}.
            </li>
          ))}
        </ul>
      </li>
    </ul>
  );
}

function happened(row, firstRelease) {
  if (row.release === firstRelease) return 'New document';
  if (row.newIssue) return 'New issue';
  return 'No new issue';
}

function WorkItems({ items }) {
  if (!items || items.length === 0) return null;
  return (
    <ul className={styles.workItems}>
      {items.map((w) => (
        <li key={w.wid || w.acronym}>
          {w.name} <span className={styles.ref}>({w.acronym}{w.ref ? `, ${w.ref}` : ''})</span>
        </li>
      ))}
    </ul>
  );
}

export default function SpecReleases({ map }) {
  const releases = useMemo(
    () => [...map.releases.analysed, ...map.releases.tracking],
    [map],
  );
  const [release, setRelease] = useState(map.releases.baseline);
  const tracked = map.releases.tracking.includes(release);
  const open = (map.releases.open || []).includes(release);

  const rows = useMemo(
    () =>
      map.documents
        .filter((d) => d.releases && d.releases[release])
        .map((d) => ({ d, row: d.releases[release] })),
    [map, release],
  );

  return (
    <div className={indexStyles.wrap}>
      <div className={indexStyles.chips} role="group" aria-label="Choose a release">
        {releases.map((r) => (
          <button
            key={r}
            type="button"
            className={`${indexStyles.chip} ${release === r ? indexStyles.chipOn : ''}`}
            aria-pressed={release === r}
            onClick={() => setRelease(r)}
          >
            Rel-{r}
            {map.releases.tracking.includes(r) || (map.releases.open || []).includes(r) ? ' (in progress)' : ''}
          </button>
        ))}
      </div>

      <p className={styles.lead}>
        {tracked
          ? `${label(release)} is followed, not analysed: the table shows the issues and work items published so far, and no statement counts.`
          : `${label(release)}${open ? ' (work in progress)' : ''}: the issue of each specification in force, and what ${label(release)} did to it.`}
      </p>

      <div className={indexStyles.tableScroll}>
        <table className={indexStyles.table}>
          <thead>
            <tr>
              <th scope="col">Specification</th>
              <th scope="col">Issue in force</th>
              <th scope="col">In this release</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(({ d, row }) => (
              <tr key={d.id}>
                <th scope="row" className={indexStyles.specCell}>
                  {d.url ? (
                    <a href={d.url} target="_blank" rel="noreferrer">{d.id}</a>
                  ) : (
                    d.id
                  )}
                </th>
                <td>
                  {d.title}
                  <span className={indexStyles.note}>{row.version}</span>
                </td>
                <td>
                  <span className={row.newIssue ? styles.new : styles.same}>
                    {happened(row, d.firstRelease)}
                  </span>
                  <WorkItems items={row.workItems} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className={styles.source}>
        Issues from the 3GPP archive; work items from the 3GPP work plan
        {map.inputs.workPlan ? ` (${map.inputs.workPlan.split('/').pop()})` : ''}. A release with no new issue of a
        specification leaves the earlier issue in force.{map.releases.tracking.length > 0 ? ` Releases after Release ${map.releases.baseline} are not covered.` : ''}
      </p>
    </div>
  );
}

// Topics: for each specification, the Technical Analysis features its statements fall under, in the issue in
// force at the baseline release.
export function SpecTopics({ map, minShare = 0.1 }) {
  const docs = map.documents.filter((d) => d.topics && d.topics.length > 0);
  return (
    <div className={indexStyles.wrap}>
      <div className={indexStyles.tableScroll}>
        <table className={indexStyles.table}>
          <thead>
            <tr>
              <th scope="col">Specification</th>
              <th scope="col">Main topics (statements)</th>
            </tr>
          </thead>
          <tbody>
            {docs.map((d) => (
              <tr key={d.id}>
                <th scope="row" className={indexStyles.specCell}>{d.id}</th>
                <td>
                  {d.topics
                    .filter((t) => t.share >= minShare)
                    .map((t) => (
                      <span key={t.name} className={indexStyles.layer} style={{ marginRight: '0.3rem' }}>
                        {t.name} ({t.statements})
                      </span>
                    ))}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className={styles.source}>
        Counts are the statements of the Release {map.releases.baseline} issue in force, placed under the
        Technical Analysis feature headings; topics under {Math.round(minShare * 100)}% of a specification's
        statements are not listed. Specifications that are reports, or belong to another project, are not
        analysed here.
      </p>
    </div>
  );
}

// Documents of other bodies listed in the normative references (clause 2) of the project's specifications, with the
// releases that list them. A tick means the document is in clause 2 of the issue in force in that release.
export function SpecOtherBodies({ map }) {
  const ob = map.otherBodies;
  const rels = map.releases.analysed;
  const bodies = [...new Set(ob.references.map((r) => r.body))];
  return (
    <div className={indexStyles.wrap}>
      <p className={styles.lead}>
        {ob.references.length} documents of other bodies are cited in the normative text of {ob.from.join(', ')}. A tick means the
        document is cited, outside notes, definitions and informative clauses, in the issue in force in that release.
        Documents that clause 2 lists but the normative text never cites are left out.
      </p>
      {bodies.map((b) => {
        const rows = ob.references.filter((r) => r.body === b);
        return (
          <details key={b} open={rows.length <= 12} className={styles.group}>
            <summary>
              {b} <span className={styles.ref}>({rows.length})</span>
            </summary>
            <div className={indexStyles.tableScroll}>
              <table className={indexStyles.table}>
                <thead>
                  <tr>
                    <th scope="col">Document</th>
                    <th scope="col">Title in the reference</th>
                    {rels.map((r) => (
                      <th key={r} scope="col">Rel-{r}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.key}>
                      <th scope="row" className={indexStyles.specCell}>{r.label === r.title ? r.title : r.label}</th>
                      <td>{r.label === r.title ? '' : r.title}</td>
                      {rels.map((x) => (
                        <td key={x} className={indexStyles.rel} title={(r.by[x] || []).join(', ')}>
                          {r.releases.includes(x) ? '\u2713' : '\u2014'}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </details>
        );
      })}
    </div>
  );
}
